"use client";

import { animate, motion, useMotionValue, useReducedMotion, type AnimationPlaybackControls, type Transition } from "motion/react";
import {
  type ComponentPropsWithoutRef,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/**
 * Props for a side panel that learns its width. `learnedWidth` is the width the
 * panel opens at, in CSS pixels: pass it with `onLearnedWidthChange` to store the
 * person's habit, or pass `defaultLearnedWidth` to let the panel hold it.
 */
export type LearnedWidthPanelProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** The content of the side panel. */
  panel: ReactNode;
  /** The main content beside the panel. */
  children: ReactNode;
  /** Names the panel and its resize handle, for example "Files". */
  panelLabel: string;
  /** False slides the panel shut. It opens again at the learned width. */
  open?: boolean;
  learnedWidth?: number;
  defaultLearnedWidth?: number;
  onLearnedWidthChange?: (width: number) => void;
  /** Smallest panel width in CSS pixels. Defaults to 160. */
  minWidth?: number;
  /** Largest panel width in CSS pixels. The main content always keeps 96px. Defaults to 360. */
  maxWidth?: number;
};

// Critically damped (40 = 2 × √400): the panel reaches its width without a wobble.
const WIDTH_SPRING: Transition = { type: "spring", stiffness: 400, damping: 40, mass: 1 };
const INSTANT: Transition = { duration: 0 };
// How far the learned width moves toward each new drag. One stray drag shifts it a little;
// a few drags in a row move it most of the way.
const LEARN_WEIGHT = 0.4;
// A drag that ends this close to the learned width lands on it exactly.
const SNAP_DISTANCE = 12;
// A change smaller than this is a nudge, not a new habit.
const NOISE = 4;
const STEP = 16;
const MAIN_MIN = 96;

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);

// The next learned width after a committed width: a weighted step toward it, or no change for a nudge.
function learnWidth(learned: number, committed: number): number {
  if (Math.abs(committed - learned) < NOISE) return learned;
  return Math.round(learned + LEARN_WEIGHT * (committed - learned));
}

/**
 * A side panel that remembers how wide the person likes it. Each plain drag of
 * the handle teaches it, weighted toward the latest drags, and a drag that ends
 * near the learned width snaps onto it. Hold Option (Alt) to size it exactly:
 * no snap, and the panel does not learn that width.
 */
export function LearnedWidthPanel({
  panel,
  children,
  panelLabel,
  open = true,
  learnedWidth,
  defaultLearnedWidth = 220,
  onLearnedWidthChange,
  minWidth = 160,
  maxWidth = 360,
  className,
  ...rootProps
}: LearnedWidthPanelProps) {
  const [ownLearned, setOwnLearned] = useState(defaultLearnedWidth);
  const learned = learnedWidth ?? ownLearned;
  const reduceMotion = useReducedMotion() ?? false;
  const panelId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const [rootWidth, setRootWidth] = useState(0);
  const [dragging, setDragging] = useState(false);
  const [current, setCurrent] = useState(learned);
  // True once a close has finished: the content then leaves the layout, so a 0px panel
  // does not keep a full-width list inside it.
  const [shut, setShut] = useState(!open);
  const width = useMotionValue(open ? learned : 0);
  const running = useRef<AnimationPlaybackControls | null>(null);
  // `last` is the width the drag shows now. A fast release can arrive before React renders the
  // last move, so the drag keeps its own copy instead of reading state.
  const drag = useRef<{ pointerId: number; startX: number; startWidth: number; precise: boolean; last: number } | null>(null);

  // The main content keeps its minimum, so the largest width depends on the frame.
  const max = Math.max(minWidth, rootWidth ? Math.min(maxWidth, rootWidth - MAIN_MIN) : maxWidth);
  const fit = (value: number) => clamp(value, minWidth, max);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const observer = new ResizeObserver(([entry]) => setRootWidth(entry.contentRect.width));
    observer.observe(root);
    return () => observer.disconnect();
  }, []);

  const moveTo = (target: number, transition: Transition) => {
    running.current?.stop();
    running.current = animate(width, target, reduceMotion ? INSTANT : transition);
    return running.current;
  };

  // The effects below run on one trigger each and read everything else from here.
  const latest = useRef({ fit, moveTo, learned, current, open });
  latest.current = { fit, moveTo, learned, current, open };

  // Opening uses the learned width and closing slides to 0. Learning a new width never
  // moves the panel: the width the person just set stays until the next open.
  useEffect(() => {
    const { fit: fitNow, moveTo: move, learned: usual } = latest.current;
    const target = open ? fitNow(usual) : 0;
    if (open) {
      setShut(false);
      setCurrent(target);
    }
    const closing = move(target, WIDTH_SPRING);
    if (!open) void closing.finished.then(() => !latest.current.open && setShut(true));
  }, [open]);

  // A narrower frame pulls an open panel back inside the new limit.
  useEffect(() => {
    const { moveTo: move, current: now, open: isOpen } = latest.current;
    if (!isOpen || drag.current || now <= max) return;
    setCurrent(max);
    move(max, WIDTH_SPRING);
  }, [max]);

  const teach = (committed: number) => {
    const next = learnWidth(learned, committed);
    if (next === learned) return;
    if (learnedWidth === undefined) setOwnLearned(next);
    onLearnedWidthChange?.(next);
  };

  const snapped = (raw: number, precise: boolean) => (!precise && Math.abs(raw - learned) <= SNAP_DISTANCE ? fit(learned) : raw);

  const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) return;
    event.preventDefault();
    event.currentTarget.setPointerCapture(event.pointerId);
    running.current?.stop();
    drag.current = { pointerId: event.pointerId, startX: event.clientX, startWidth: width.get(), precise: event.altKey, last: current };
    setDragging(true);
  };

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const state = drag.current;
    if (!state || state.pointerId !== event.pointerId) return;
    state.precise = event.altKey;
    const raw = fit(state.startWidth + event.clientX - state.startX);
    const target = snapped(raw, state.precise);
    // The width follows the finger; only the jump onto the learned width springs.
    if (target === raw) {
      running.current?.stop();
      width.set(raw);
    } else if (target !== state.last) {
      moveTo(target, WIDTH_SPRING);
    }
    state.last = target;
    setCurrent(target);
  };

  const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
    const state = drag.current;
    if (!state || state.pointerId !== event.pointerId) return;
    drag.current = null;
    setDragging(false);
    if (!state.precise) teach(state.last);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const precise = event.altKey;
    const step = precise ? 1 : STEP;
    let next: number | null = null;
    if (event.key === "ArrowRight") next = fit(current + step);
    else if (event.key === "ArrowLeft") next = fit(current - step);
    else if (event.key === "Home") next = minWidth;
    else if (event.key === "End") next = max;
    else if (event.key === "Enter") next = fit(learned);
    if (next === null) return;
    event.preventDefault();
    setCurrent(next);
    moveTo(next, WIDTH_SPRING);
    if (!precise && event.key !== "Enter") teach(next);
  };

  // Double-clicking the handle puts the panel back at the learned width.
  const reset = () => {
    const target = fit(learned);
    setCurrent(target);
    moveTo(target, WIDTH_SPRING);
  };

  return (
    <div ref={rootRef} {...rootProps} className={cn("relative flex w-full min-w-0 overflow-hidden", className)}>
      <motion.div
        id={panelId}
        role="region"
        aria-label={panelLabel}
        inert={!open}
        style={{ width }}
        className="relative shrink-0 overflow-hidden"
      >
        {/* The content keeps its width while the panel slides, so text never rewraps mid-slide. */}
        <motion.div hidden={shut} style={{ width: open ? current : fit(learned) }} className="h-full">
          {panel}
        </motion.div>
      </motion.div>

      {open && (
        <div
          role="separator"
          tabIndex={0}
          aria-orientation="vertical"
          aria-controls={panelId}
          aria-label={`Resize ${panelLabel.toLowerCase()} panel`}
          aria-valuemin={minWidth}
          aria-valuemax={max}
          aria-valuenow={Math.round(current)}
          aria-valuetext={`${Math.round(current)} pixels${Math.round(current) === fit(learned) ? ", your usual width" : ""}`}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerCancel={handlePointerUp}
          onKeyDown={handleKeyDown}
          onDoubleClick={reset}
          className="group relative z-10 -mx-5.5 w-11 shrink-0 cursor-col-resize touch-none outline-none"
        >
          <span
            aria-hidden="true"
            className={cn(
              "absolute inset-y-0 left-1/2 w-px -translate-x-1/2 bg-border motion-safe:transition-colors motion-safe:duration-150",
              "group-focus-visible:w-0.5 group-focus-visible:bg-ring",
              dragging ? "w-0.5 bg-foreground" : "group-hover:bg-muted-foreground",
            )}
          />
        </div>
      )}

      {/* While a drag runs, a tick marks the learned width, so the snap never comes as a surprise. */}
      {dragging && (
        <motion.span
          aria-hidden="true"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          style={{ x: fit(learned) }}
          className="pointer-events-none absolute top-0 left-0 z-20 h-2 w-0.5 -translate-x-1/2 rounded-full bg-foreground"
        />
      )}

      <div className="min-w-0 flex-1">{children}</div>
    </div>
  );
}
